21. package fr.pilato.elasticsearch.crawler.plugins.fs.s3;
22. 
23. import com.jayway.jsonpath.PathNotFoundException;
24. import fr.pilato.elasticsearch.crawler.fs.beans.Doc;
25. import fr.pilato.elasticsearch.crawler.fs.framework.FsCrawlerIllegalConfigurationException;
26. import fr.pilato.elasticsearch.crawler.fs.framework.FsCrawlerUtil;
27. import fr.pilato.elasticsearch.crawler.fs.settings.FsSettings;
28. import fr.pilato.elasticsearch.crawler.plugins.FsCrawlerExtensionFsProviderAbstract;
29. import fr.pilato.elasticsearch.crawler.plugins.FsCrawlerPlugin;
30. import fr.pilato.elasticsearch.crawler.plugins.FsCrawlerPluginException;
31. import io.minio.GetObjectArgs;
32. import io.minio.GetObjectResponse;
33. import io.minio.MinioClient;
34. import io.minio.errors.MinioException;
35. import java.io.IOException;
36. import java.io.InputStream;
37. import java.security.InvalidKeyException;
38. import java.security.NoSuchAlgorithmException;
39. import org.apache.logging.log4j.LogManager;
40. import org.apache.logging.log4j.Logger;
41. import org.pf4j.Extension;
42. 
43. public class FsS3Plugin extends FsCrawlerPlugin {
44.     private static final Logger logger = LogManager.getLogger();
45. 
46.     @Override
47.     protected String getName() {
48.         return "fs-s3";
49.     }
50. 
51.     @Extension
52.     public static class FsCrawlerExtensionFsProviderS3 extends FsCrawlerExtensionFsProviderAbstract {
53. 
54.         private MinioClient minioClient;
55.         private String bucket;
56.         private String url;
57.         private String accesKey;
58.         private String secretKey;
59.         private String object;
60. 
61.         @Override
62.         public String getType() {
63.             return "s3";
64.         }
65. 
66.         @Override
67.         protected void parseSettings() throws PathNotFoundException {
68.             bucket = document.read("$.s3.bucket");
69.             object = document.read("$.s3.object");
70.             url = document.read("$.s3.url");
71.             accesKey = document.read("$.s3.access_key");
72.             secretKey = document.read("$.s3.secret_key");
73.         }
74. 
75.         @Override
76.         protected void validateSettings() throws PathNotFoundException {
77.             if (FsCrawlerUtil.isNullOrEmpty(url)) {
78.                 throw new FsCrawlerIllegalConfigurationException("S3 URL is missing");
79.             }
80.             if (FsCrawlerUtil.isNullOrEmpty(bucket)) {
81.                 throw new FsCrawlerIllegalConfigurationException("S3 bucket is missing");
82.             }
83.             if (FsCrawlerUtil.isNullOrEmpty(object)) {
84.                 throw new FsCrawlerIllegalConfigurationException("S3 object is missing");
85.             }
86.         }
87. 
88.         @Override
89.         public void start(FsSettings fsSettings, String restSettings) {
90.             super.start(fsSettings, restSettings);
91.             minioClient = MinioClient.builder()
92.                     .endpoint(url)
93.                     .credentials(accesKey, secretKey)
94.                     .build();
95.         }
96. 
97.         @Override
98.         public void stop() throws FsCrawlerPluginException {
99.             super.stop();
100.             logger.trace("Closing FsCrawlerExtensionFsProviderS3");
101.             if (minioClient != null) {
102.                 logger.debug("Closing minioClient");
103.                 try {
104.                     minioClient.close();
105.                 } catch (Exception e) {
106.                     throw new FsCrawlerPluginException("Error while closing S3 client", e);
107.                 }
108.                 minioClient = null;
109.             }
110.         }
111. 
112.         @Override
113.         public InputStream readFile() throws FsCrawlerPluginException {
114.             logger.debug("Reading S3 file [{}] from bucket [{}/{}]", object, url, bucket);
115.             GetObjectArgs getObjectArgs =
116.                     GetObjectArgs.builder().bucket(bucket).object(object).build();
117.             try {
118.                 return minioClient.getObject(getObjectArgs);
119.             } catch (MinioException | IOException | InvalidKeyException | NoSuchAlgorithmException e) {
120.                 logger.debug("Failed to read file", e);
121.                 throw new FsCrawlerPluginException(
122.                         "IOException caught while getting object " + object + " from bucket " + bucket + ":"
123.                                 + e.getMessage(),
124.                         e);
125.             }
126.         }
127. 
128.         private long getFilesize() throws FsCrawlerPluginException {
129.             logger.debug("Reading S3 filesize for file [{}] from bucket [{}/{}]", object, url, bucket);
130.             GetObjectArgs getObjectArgs =
131.                     GetObjectArgs.builder().bucket(bucket).object(object).build();
132.             try (GetObjectResponse response = minioClient.getObject(getObjectArgs)) {
133.                 logger.trace("S3 response headers [{}]", response.headers());
134.                 return Long.parseLong(response.headers().get("Content-Length"));
135.             } catch (InvalidKeyException | NoSuchAlgorithmException e) {
136.                 logger.debug("Failed to read file", e);
137.                 throw new FsCrawlerIllegalConfigurationException(e.getMessage());
138.             } catch (MinioException | IOException e) {
139.                 throw new FsCrawlerPluginException(
140.                         "Can not get file size for object " + object + " of bucket " + bucket, e);
141.             }
142.         }
143. 
144.         @Override
145.         public Doc createDocument() throws FsCrawlerPluginException {
146.             logger.debug("Creating document from {}", object);
147.             Doc doc = new Doc();
148.             doc.getFile().setFilename(object);
149.             doc.getPath().setVirtual(object);
150.             doc.getPath().setReal(object);
151.             doc.getFile().setFilesize(getFilesize());
152.             return doc;
153.         }
154.     }
155. }
156.

